from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    """Return x squared."""
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Return [square(x) for x in xs], computed in a thread pool.

    The output preserves input order. An empty input returns an empty list.
    """
    with ThreadPoolExecutor() as ex:
        return list(ex.map(square, xs))


def test_squares_empty() -> None:
    assert squares([]) == []


def test_squares_basic() -> None:
    assert squares([1, 2, 3]) == [1, 4, 9]


def test_squares_negatives_and_zero() -> None:
    assert squares([-3, 0, -1]) == [9, 0, 1]


def test_squares_preserves_order() -> None:
    xs = list(range(-500, 500))
    assert squares(xs) == [x * x for x in xs]


def test_square_single() -> None:
    assert square(7) == 49


@pytest.mark.parametrize(("x", "expected"), [(0, 0), (1, 1), (-4, 16)])
def test_square_parametrized(x: int, expected: int) -> None:
    assert square(x) == expected


def test_squares_uses_thread_pool() -> None:
    # Confirms the executor type is importable and usable; the implementation
    # is expected to dispatch work through a ThreadPoolExecutor.
    with ThreadPoolExecutor(max_workers=2) as ex:
        assert list(ex.map(square, [2, 3])) == [4, 9]
    assert squares([2, 3]) == [4, 9]
